**Trie contains 'cat', 'cats', 'car'. Deleting 'cats' must not affect 'cat'. What's the deletion strategy to avoid breaking shared prefixes?**

```python
def delete(node, word, depth):
    if depth == len(word):
        node.is_end_of_word = False
        return node.has_no_children()  # Delete node if no children

    char = word[depth]
    if char in node.children:
        should_delete = delete(node.children[char], word, depth + 1)
        if should_delete:
            del node.children[char]
            return not node.is_end_of_word and node.has_no_children()

    return False
```

**Why check for children and end markers?**

**Word frequency counter tracks how many words start with prefix 'pre'. Words: 'prefix', 'prepare', 'present', 'preview', 'apple'. Trie stores count at each node. What's the query complexity?**

```python
class TrieNode:
    def __init__(self):
        self.children = {}
        self.prefix_count = 0  # Words passing through this node
        self.is_end = False

def count_prefix(root, prefix):
    node = root
    for char in prefix:
        if char not in node.children:
            return 0
        node = node.children[char]
    return node.prefix_count
```

**Why store prefix count during insertion?**

**Design data structure supporting: addWord('bad'), addWord('dad'), search('bad')→true, search('.ad')→true (. matches any char). How to handle wildcard search in trie?**

```python
def search(node, word, index):
    if index == len(word):
        return node.is_end

    char = word[index]
    if char == '.':
        # Try all children
        for child in node.children.values():
            if search(child, word, index + 1):
                return True
        return False
    else:
        if char not in node.children:
            return False
        return search(node.children[char], word, index + 1)
```

**What's the worst-case complexity with wildcards?**

**Boggle: 4×4 grid with letters, find all dictionary words by moving to adjacent cells. Dictionary: 100K words. Naive: DFS from each cell checking each word O(16 × 8^max_len × 100K). How does trie + DFS optimize?**

```python
def find_words(board, trie):
    results = set()

    def dfs(i, j, node, path):
        if node.is_end:
            results.add(path)

        char = board[i][j]
        if char not in node.children:
            return  # No words with this prefix, prune

        board[i][j] = '#'  # Mark visited
        for di, dj in [(0,1),(1,0),(0,-1),(-1,0)]:
            ni, nj = i+di, j+dj
            if valid(ni, nj) and board[ni][nj] != '#':
                dfs(ni, nj, node.children[char], path + char)
        board[i][j] = char  # Restore
```

**Why does trie pruning dramatically reduce search space?**

**Search autocomplete returns top 5 results by popularity. Trie nodes store frequency counts. For prefix 'face', must traverse entire subtree to find top 5. What optimization enables O(1) top-k retrieval?**

```python
class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False
        self.top_k = []  # Maintain top k results at each node

def insert_with_frequency(root, word, freq):
    node = root
    for char in word:
        if char not in node.children:
            node.children[char] = TrieNode()
        node = node.children[char]
        # Update top_k at each node on path
        update_top_k(node.top_k, word, freq, k=5)
    node.is_end = True
```

